// Independent original-MMIO MSAA adversary. No guest packet or pixel fixture is
// generated by the renderer under test; native observation never replaces GL.
import {checker,makeRig,context,idCommand,header,backing,transfer,submission} from '../../renderer/virgl-command/tests/submit-acceptance.mjs';
import {packet,join,shader,word} from '../virgl-command/standard-image-fixtures.mjs';
import {createVirglProductionBridge} from '../../renderer/virgl-command/control-bridge.mjs';
import {qualifyVirglHost,createWorkerScanoutPresenter} from '../../renderer/virgl-command/production.mjs';
import {createVirglStandardStreamOutputShaderBridge} from '../../renderer/virgl-shader/standard.mjs';

const copy = value => JSON.parse(JSON.stringify(value, (_,v) => ArrayBuffer.isView(v) ? [...v] : typeof v === 'bigint' ? v.toString() : v));
const put = (bytes,at,value) => new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength).setUint32(at,value,true);
function allocation(id,format,bind,samples,target=2,width=12,height=12) {
  const bytes=header(0x204,0,72);
  [id,target,format,bind,width,height,1,1,0,samples,0,0].forEach((v,i)=>put(bytes,24+i*4,v));
  return bytes;
}
// Mesa26.2.2 virgl_encode_blit(), words mask/scissor/destination/source.
function blit(src,dst,format=67,mask=15,side=12) {
  return packet(16,0,[mask,0,0,dst,0,format,0,0,0,side,side,1,src,0,format,0,0,0,side,side,1]);
}
function clear(mask,color,depth=.75) {
  const encoded=new DataView(new ArrayBuffer(8));encoded.setFloat64(0,depth,true);
  return packet(7,0,[mask,...color.map(word),encoded.getUint32(0,true),encoded.getUint32(4,true),0]);
}
const vs='VERT\nDCL IN[0]\nDCL OUT[0], POSITION\n0: MOV OUT[0], IN[0]\n1: END\n';
const fs='FRAG\nDCL OUT[0], COLOR\nIMM[0] FLT32 {1,0,1,1}\n0: MOV OUT[0], IMM[0]\n1: END\n';

async function one(Wasm,qualification,native,compiler,schedule) {
  const c=checker(),row={name:'independent-msaa-'+schedule,status:'running',native:[],predictions:{
    color:'A four-sample magenta clear resolves every pixel to255,0,255,255.',
    depth:'Four-sample Z16 depth0.75 resolves every word to49151 (rounding tolerance1).',
    rgbx:'Four-sample BGRX storage resolves byte color and forces the unused alpha byte to255.',
    coverage:'A magenta triangle on green resolves interior/exterior exactly and at least one mixed edge; channel sums remain255.',
    rejection:'Unsupported metadata, sample direction/stretch and original format changes never reach native blit.',
    lifetime:'Original destroy/unref remains queued until a retained physical resolve completes.',
  }};
  const nativeOwners=new Map();let nextOwner=0;
  const observed=new Proxy(native,{get(target,name){const method=Reflect.get(target,name,target);if(typeof method!=='function')return method;
    return(...args)=>{
      const entry={sequence:row.native.length,name,args:args.map(v=>ArrayBuffer.isView(v)?[...v]:v&&typeof v==='object'?nativeOwners.get(v)||v.constructor.name:v)};
      row.native.push(entry);const result=method.apply(target,args);
      if(name==='createRenderbuffer'&&result){nativeOwners.set(result,++nextOwner);entry.owner=nextOwner;}
      if(name==='deleteRenderbuffer')nativeOwners.delete(args[0]);
      if(name==='renderbufferStorageMultisample'){
        entry.actualSamples=target.getRenderbufferParameter(target.RENDERBUFFER,target.RENDERBUFFER_SAMPLES);
        c.equal(entry.actualSamples,args[1],'physical native samples equal original request');
      }
      return result;
    };
  }});
  const Selected=class {constructor(callback){return Wasm.qualified(callback,qualification.hostWords,qualification.formatRoles,qualification.renderer);}};
  const rig=makeRig(Selected,opts=>createVirglProductionBridge({...opts,presenter:createWorkerScanoutPresenter(()=>{})}),observed,compiler,c,schedule,true,false,true);
  const output=rig.q.base+0x220000n,input=rig.q.base+0x210000n;
  const nativeBlits=()=>row.native.filter(v=>v.name==='blitFramebuffer').length;
  const read=async(id,n)=>{
    const index=rig.exchanges.length;
    await rig.expect('independent actual resolved DMA'+id,transfer(1,id,2,[0,0,0,12,12,1],0n,0,0,0x20000000000001n));
    const bytes=Uint8Array.from(rig.exchanges[index].bytes.match(/../g).map(v=>parseInt(v,16)));
    c.equal(bytes.length,n,'complete real original readback');return bytes;
  };
  try {
    await rig.expect('independent original context',context(1));
    for(const [id,format,bind,samples] of [[1,67,2,4],[2,67,2,0],[3,16,1,4],[4,16,1,0],[6,67,2,2],[7,2,2,4],[8,2,2,0]]){
      await rig.expect('independent original allocation'+id,allocation(id,format,bind,samples));
      await rig.expect('independent original membership'+id,idCommand(0x202,1,id));
    }
    await rig.expect('independent color backing',backing(2,[[output,4096]]));
    await rig.expect('independent depth backing',backing(4,[[output+0x2000n,4096]]));
    await rig.expect('independent RGBX backing',backing(8,[[output+0x4000n,4096]]));
    await rig.expect('independent four-sample color+depth clear',submission(1,join(
      packet(1,8,[20,1,67,0,0]),packet(1,8,[21,3,16,0,0]),packet(1,8,[26,6,67,0,0]),
      packet(5,0,[1,21,20]),clear(5,[1,0,1,1]),blit(1,2),blit(3,4,16,16)),71n));
    row.clearPixels=[...await read(2,576)];
    for(let i=0;i<144;i++)c.same(row.clearPixels.slice(i*4,i*4+4),[255,0,255,255],'independent every resolved clear pixel'+i);
    const depths=await read(4,288);row.depthPixels=[...depths];
    for(const value of new Uint16Array(depths.buffer))c.truth(Math.abs(value-49151)<=1,'independent three-quarter resolved depth');
    await rig.expect('independent RGBX multisample clear and resolve',submission(1,join(
      packet(1,8,[27,7,2,0,0]),packet(5,0,[1,0,27]),clear(4,[.25,.5,.75,0]),blit(7,8,2)),72n));
    row.rgbxPixels=[...await read(8,576)];
    for(let i=0;i<144;i++){
      const actual=row.rgbxPixels.slice(i*4,i*4+4);
      for(let k=0;k<3;k++)c.truth(Math.abs(actual[k]-[191,128,64][k])<=1,'independent BGRX byte channel');
      c.equal(actual[3],255,'unused BGRX alpha remains opaque after native resolve');
    }
    await rig.expect('independent single-sample depth surface',submission(1,packet(1,8,[24,4,16,0,0])));
    for(const [name,fields] of [['mixed color/depth',[1,24,20]],['mixed color targets',[2,0,20,26]]]){
      const before=copy(rig.host.bridge.inspect().renderer.contexts[0].subContexts[0].bindings),nativeAt=row.native.length;
      await rig.expect('independent framebuffer sample mismatch '+name,submission(1,packet(5,0,fields),74n),0x1205);
      const after=copy(rig.host.bridge.inspect().renderer.contexts[0].subContexts[0].bindings);
      c.same(after.framebuffer,before.framebuffer,'mismatched samples preserve original color bindings');
      c.same(after.depthSurface,before.depthSurface,'mismatched samples preserve original depth binding');
      c.truth(!row.native.slice(nativeAt).some(v=>v.name==='bindFramebuffer'||v.name==='framebufferRenderbuffer'),
        'mismatched samples reject before native attachment effects');
    }
    // Vertex data and shader are literal and unrelated to the worker triangle.
    await rig.expect('independent original vertex storage',allocation(5,64,16,0,0,48,1));
    await rig.expect('independent vertex membership',idCommand(0x202,1,5));
    await rig.expect('independent vertex backing',backing(5,[[input,48]]));
    rig.q.write(input,new Uint8Array(new Float32Array([-1,-1,0,1,.875,-1,0,1,-1,.875,0,1]).buffer));
    await rig.expect('independent vertex DMA',transfer(1,5,1,[0,0,0,48,1,1]));
    await rig.expect('independent literal diagonal and resolve',submission(1,join(
      shader(10,0,vs),shader(11,1,fs),packet(31,0,[10,0]),packet(31,0,[11,1]),
      packet(1,5,[12,0,0,0,31]),packet(2,5,[12]),packet(6,0,[16,0,5]),
      packet(4,0,[0,...[6,6,.5,6,6,.5].map(word)]),packet(5,0,[1,0,20]),
      clear(4,[0,1,0,1]),packet(1,2,[40,2|1<<29|1<<25,word(1),0,0xffff,word(1),0,0,0]),
      packet(2,2,[40]),packet(8,0,[0,3,4,0,1,0,0,0,0,0,0xffffffff,0]),blit(1,2)),73n));
    const pixels=await read(2,576);row.edgePixels=[...pixels];row.partialPixels=[];
    for(let y=0;y<12;y++)for(let x=0;x<12;x++){
      const at=(y*12+x)*4,[red,green,blue,alpha]=pixels.slice(at,at+4);
      c.equal(alpha,255,'independent alpha');c.equal(red,blue,'independent magenta coverage');
      c.truth(Math.abs(red+green-255)<=1,'independent complementary sample colors');
      if(x+y<=8)c.same([...pixels.slice(at,at+4)],[255,0,255,255],'independent triangle interior');
      if(x+y>=12)c.same([...pixels.slice(at,at+4)],[0,255,0,255],'independent triangle exterior');
      if(red>0&&red<255)row.partialPixels.push({x,y,pixel:[red,green,blue,alpha]});
    }
    c.truth(row.partialPixels.length>0,'actual native mixed sample pixels survive original resolve');
    for(const n of [1,3,5,8,0xffffffff]){
      const before=row.native.length;
      await rig.expect('independent refused samples'+n,allocation(90,67,2,n),0x1205);
      c.truth(!row.native.slice(before).some(v=>v.name==='createRenderbuffer'),'bad samples cause no native allocation');
    }
    for(const [label,bytes] of [
      ['3D shape',allocation(91,67,2,4,3)],['mipmap',(()=>{const b=allocation(91,67,2,4);put(b,56,1);return b;})()],
      ['flags',(()=>{const b=allocation(91,67,2,4);put(b,64,1);return b;})()],
      ['sample budget',allocation(91,67,2,4,2,2048,1025)],
    ]) await rig.expect('independent refused '+label,bytes,label==='sample budget'?0x1201:0x1205);
    for(const [label,bytes] of [
      ['negative origin',(()=>{const b=blit(1,2);put(b,7*4,-1);return b;})()],
      ['one-past source',(()=>{const b=blit(1,2);put(b,16*4,1);return b;})()],
      ['stretch',(()=>{const b=blit(1,2);put(b,10*4,11);return b;})()],
      ['linear resolve',(()=>{const b=blit(1,2);put(b,4,15|256);return b;})()],
      ['format reinterpretation',blit(1,2,104)],['sample expansion',blit(2,1)],['sample mismatch',blit(1,6)],
    ]){
      const before=nativeBlits();await rig.expect('independent BLIT refused '+label,submission(1,bytes,79n),0x1205);
      c.equal(nativeBlits(),before,'refused BLIT has no native copy');
    }
    const first=rig.q.enqueue('independent queued retained resolve',submission(1,blit(1,2),83n));
    const destroy=rig.q.enqueue('independent destroy while resolve retained',header(0x201,1,24));
    const unrefs=[1,2,3,4,5,6,7,8].map(id=>rig.q.enqueue('independent unref while resolve retained'+id,idCommand(0x102,0,id)));
    rig.q.kick();rig.q.run();c.equal(rig.q.usedIndex(),first.number,'original resolve owns head');
    await rig.step();c.equal(rig.q.usedIndex(),first.number,'native fence does not publish guest head');
    c.truth(rig.host.bridge.inspect().renderer.jobs.imageSources>=2,'both native resources held during actual resolve');
    await rig.drain();for(const entry of [first,destroy,...unrefs])rig.q.collect(entry);
    row.nativeSamples=row.native.filter(v=>v.name==='renderbufferStorageMultisample').map(v=>({requested:v.args[1],actual:v.actualSamples}));
    c.truth(row.nativeSamples.some(v=>v.requested===4&&v.actual===4),'actual four-sample proof');
    c.truth(row.nativeSamples.some(v=>v.requested===2&&v.actual===2),'actual two-sample proof');
    c.equal(native.getError(),native.NO_ERROR,'zero actual WebGL error');row.status='passed';
  } catch(error) {row.status='failed';row.failure={message:error.message,stack:error.stack};}
  finally {
    row.records=copy(rig.q.records);row.events=copy(rig.events);row.exchanges=copy(rig.exchanges);row.completions=copy(rig.completions);
    row.beforeDispose=copy(rig.host.bridge.inspect());row.guestTrace=rig.q.vm.commandTrace();row.machineDigest=rig.q.vm.machineDigest();
    row.disposed=copy(rig.host.bridge.dispose());rig.q.vm.free();row.cleaned=rig.trace.snapshot();row.liveRenderbuffers=nativeOwners.size;row.assertions=c.assertions;
    if(row.cleaned.liveObjects||row.cleaned.liveSyncs||nativeOwners.size){row.status='failed';row.cleanupFailure='Native owners leaked';}
  }
  return row;
}
async function historicalRefusal(Wasm,native,compiler) {
  const c=checker(),row={name:'historical-sample-refusal',predictions:{
    admission:'The unchanged historical proof rejects2/4 sample metadata before any host event and exposes no capset.'}};
  const rig=makeRig(Wasm,opts=>createVirglProductionBridge({...opts,presenter:createWorkerScanoutPresenter(()=>{})}),native,compiler,c,19,true,false,true);
  try {
    c.equal(rig.q.vm.readMmio(0x10c),0,'historical proof has no positive production capset');
    for(const samples of [2,4]){
      const before=rig.events.length;
      await rig.expect('historical original sample refusal'+samples,allocation(1,67,2,samples),0x1205);
      c.equal(rig.events.length,before,'historical refusal does not call host');
    }
    row.status='passed';
  }catch(error){row.status='failed';row.failure={message:error.message,stack:error.stack};}
  finally{row.records=copy(rig.q.records);row.guestTrace=rig.q.vm.commandTrace();row.disposed=copy(rig.host.bridge.dispose());rig.q.vm.free();row.cleaned=rig.trace.snapshot();row.assertions=c.assertions;}
  return row;
}
async function physicalLoss(Wasm,compiler) {
  const canvas=document.createElement('canvas');canvas.width=canvas.height=12;
  const native=canvas.getContext('webgl2',{antialias:false,failIfMajorPerformanceCaveat:true});
  const qualification=await qualifyVirglHost(native),c=checker(),row={name:'physical-msaa-loss',native:[],predictions:{
    loss:'Losing the actual context while a native BLIT fence owns both resources posts an unsuccessful completion, retires the original head and releases all renderbuffer/fence owners.'}};
  const live=new Set();
  const observed=new Proxy(native,{get(target,name){const method=Reflect.get(target,name,target);if(typeof method!=='function')return method;
    return(...args)=>{const result=method.apply(target,args);row.native.push({name,args:args.map(v=>v&&typeof v==='object'?v.constructor.name:v)});
      if(name==='createRenderbuffer'&&result)live.add(result);if(name==='deleteRenderbuffer')live.delete(args[0]);return result;};}});
  const Selected=class{constructor(callback){return Wasm.qualified(callback,qualification.hostWords,qualification.formatRoles,qualification.renderer);}};
  const rig=makeRig(Selected,opts=>createVirglProductionBridge({...opts,presenter:createWorkerScanoutPresenter(()=>{})}),observed,compiler,c,65537,true,false,true);
  try{
    await rig.expect('loss original context',context(1));
    for(const [id,samples]of [[1,4],[2,0]]){
      await rig.expect('loss original resource'+id,allocation(id,67,2,samples));
      await rig.expect('loss original membership'+id,idCommand(0x202,1,id));
    }
    await rig.expect('loss original sample clear',submission(1,join(packet(1,8,[20,1,67,0,0]),packet(5,0,[1,0,20]),clear(4,[1,0,1,1])),97n));
    const entry=rig.q.enqueue('physical loss during original resolve',submission(1,blit(1,2),101n),0x1200);
    rig.q.kick();rig.q.run();await rig.step();
    c.equal(rig.q.usedIndex(),entry.number,'native pending resolve retains original head');
    row.beforeLoss=copy(rig.host.bridge.inspect());
    c.truth(row.beforeLoss.renderer.jobs.imageSources>=2,'physical loss occurs with both resources held');
    c.truth(rig.trace.syncs.size>0,'physical loss occurs with a real pending native sync');
    canvas.addEventListener('webglcontextlost',event=>event.preventDefault(),{once:true});
    native.getExtension('WEBGL_lose_context').loseContext();
    for(let i=0;i<100&&!native.isContextLost();i++)await new Promise(resolve=>setTimeout(resolve,1));
    c.equal(native.isContextLost(),true,'actual hardware context lost');
    await new Promise(resolve=>setTimeout(resolve,0));rig.trace.nextTurn();
    row.afterLossPump=copy(rig.host.bridge.pump());rig.q.run();
    c.equal(rig.q.usedIndex(),entry.number+1,'uncertain native completion retires original head');
    rig.q.collect(entry);
    c.equal(rig.completions.at(-1).args[4],false,'lost native resolve cannot claim completed GPU pixels');
    c.equal(rig.host.bridge.inspect().renderer.jobs.imageSources,0,'lost resolve releases both retained resources');
    c.equal(rig.trace.syncs.size,0,'lost resolve retires native fence');row.status='passed';
  }catch(error){row.status='failed';row.failure={message:error.message,stack:error.stack};}
  finally{
    row.records=copy(rig.q.records);row.events=copy(rig.events);row.completions=copy(rig.completions);row.guestTrace=rig.q.vm.commandTrace();row.machineDigest=rig.q.vm.machineDigest();
    row.beforeDispose=copy(rig.host.bridge.inspect());row.disposed=copy(rig.host.bridge.dispose());rig.q.vm.free();row.cleaned=rig.trace.snapshot();row.liveRenderbuffers=live.size;row.assertions=c.assertions;
    if(row.cleaned.liveObjects||row.cleaned.liveSyncs||live.size){row.status='failed';row.cleanupFailure='Native loss owners leaked';}
  }
  return row;
}
export async function runProductionMultisampleCritic({WasmVirglSubmitProof,schedules=[7,31337]}) {
  const native=document.querySelector('#gpu').getContext('webgl2',{antialias:false,failIfMajorPerformanceCaveat:true});
  if(!native)throw Error('Native hardware WebGL2 required');
  const qualification=await qualifyVirglHost(native),compiler=await createVirglStandardStreamOutputShaderBridge();
  const report={status:'running',qualification:copy(qualification),rows:[],actualLinuxGuest:false,productionConstructor:true};
  window.__productionCriticReport=report;
  for(const schedule of schedules){
    const row=await one(WasmVirglSubmitProof,qualification,native,compiler,schedule),index=report.rows.length;
    const pin=await window.__recordProductionCriticRun(index,JSON.stringify(row));
    report.rows.push({...pin,name:row.name,status:row.status,...(row.failure?{failure:row.failure}:{})});
  }
  for(const row of [await historicalRefusal(WasmVirglSubmitProof,native,compiler),await physicalLoss(WasmVirglSubmitProof,compiler)]){
    const pin=await window.__recordProductionCriticRun(report.rows.length,JSON.stringify(row));
    report.rows.push({...pin,name:row.name,status:row.status,...(row.failure?{failure:row.failure}:{})});
  }
  report.status=report.rows.every(row=>row.status==='passed')?'passed':'failed';
  report.summary={status:report.status,runs:report.rows.length,failed:report.rows.filter(row=>row.status!=='passed'),hardware:qualification.identity};
  return report;
}
